import{z as n,x as B,o as t,c as p,q as l,j as E,D as e,d as r,s as o,S as s}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"ILT 正则化","description":"","frontmatter":{"title":"ILT 正则化","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/ilt-regularization.md","filePath":"litho/ilt-regularization.md","lastUpdated":1791413859000}'),A={name:"litho/ilt-regularization.md"};function d(h,a,T,_,c,m){const i=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=l('<h1 id="ilt-正则化" tabindex="-1">ILT 正则化 <a class="header-anchor" href="#ilt-正则化" aria-label="Permalink to &quot;ILT 正则化&quot;">​</a></h1><div class="epigraph"><p>逆问题的精确解有无穷多个掩模，都几乎给出同一张低通空中像；不正则，优化器就在像素噪声里打转，写出不可制造的纹理。</p><footer>—— 对照逆光刻文献对病态逆问题与可制造约束的通称</footer></div><p><a href="/litho/ilt-curvilinear">上一课</a>已经把 ILT 收成：对前向成像求逆，表示从多边形边换成像素或水平集，曲线是通带内梯度下降的自然几何。缺口是病态。许多掩模对应几乎相同的晶圆轮廓，噪声和模型误差会被放大成高频碎形。必须正则化——平滑、MRC、剂量/焦点鲁棒——解才稳定到能写、能检、能蚀。本课钉正则。掩模厂用哪些几何规则把正则落地，留给<a href="/litho/mask-rule-check">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>正向 \\(I=\\mathcal{I}(M)\\) 是低通的。逆「给定 \\(I\\) 求 \\(M\\)」的解空间巨大：在截止频率以外加减任意纹理，空中像几乎不变，损失几乎不动。无约束梯度下降会把模型误差和数值噪声拟合进这些零空间，看起来 loss 很低，硅上却是新热区，掩模数据体积爆炸。</p><p><span class="marginnote">「零空间」可以想象成光看不见的涂鸦区：在这些像素上乱改，经过透镜后的空中像几乎不变。无约束的优化器就会把模型误差、数值噪声全画进这片盲区——loss 表面很漂亮，掩模却成了棋盘废品。正则化的本质就是给盲区装上斜率，让优化器主动绕开它。</span></p><p>OPC 的曼哈顿碎片本身就是一种硬正则：边只能法向挪、拓扑锁定。ILT 丢掉这层约束之后，必须显式把可制造性写进目标或投影，否则「光学上更优」会变成「掩模厂拒收」。缺口因此是选哪些惩罚、何时投影，而不是再证明逆问题存在。</p><h3 id="正则不是把曲线变回直角" tabindex="-1">正则不是把曲线变回直角 <a class="header-anchor" href="#正则不是把曲线变回直角" aria-label="Permalink to &quot;正则不是把曲线变回直角&quot;">​</a></h3><p>常见误解是：正则化 = 强制曼哈顿。那只是正则族里的一种，而且通常抬高损失、缩小窗口——上一课正是靠去掉它才换光学收益。曲线 ILT 的正则是曲率、最小宽度/间距、面积、以及 PV 扰动下的损失，让解停在光滑可写的流形上，而不是停在像素棋盘上。</p><p><span class="marginnote">「通称」的意思是：平滑、Tikhonov、总变差、水平集周长、MRC 投影、鲁棒项，文献里名字不同，目的相同——压零空间、换稳定性。本课不绑某一家 EDA 的产品名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三项几乎总是同时在。平滑：对 \\(M\\) 的梯度或曲率惩罚，或在更新后做低通，禁止单像素抖动。可制造：每步或每若干步投影到 MRC（最小 CD、间距、面积；曲线还要曲率半径）。鲁棒：在剂量、焦点、掩模误差的若干扰动上求和损失，避免只在名义点漂亮。三者权重是超参数：平滑太重，窗口吐回去，ILT 退化成模糊的 OPC；太轻，解不可写。</p><p>输出仍要提取等值线、对齐电子束网格。正则若只存在于优化器、不存在于提取后的多边形，后处理会把正则偷偷拆掉。工程上把「优化内投影」和「提取后简化」当成同一条链。</p>',13)),(t(),E(s,null,{default:e(()=>[o(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20NS%5B%22%E9%9B%B6%E7%A9%BA%E9%97%B4%E7%BA%B9%E7%90%86%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20SMOOTH%5B%22%E5%B9%B3%E6%BB%91%E6%83%A9%E7%BD%9A%22%5D%0A%20%20SMOOTH%20--%3E%20F1%5B%22%E6%8C%89%E4%BD%8F%E5%8D%95%E5%83%8F%E7%B4%A0%E6%8A%96%E5%8A%A8%22%5D%0A%20%20UNW%5B%22%E4%B8%8D%E5%8F%AF%E5%86%99%E5%87%A0%E4%BD%95%22%5D%20--%3E%20MRC%5B%22MRC%20%E6%8A%95%E5%BD%B1%22%5D%0A%20%20MRC%20--%3E%20F2%5B%22%E5%BC%BA%E5%88%B6%E6%9C%80%E5%B0%8F%20CD%20%2F%20%E9%97%B4%E8%B7%9D%20%2F%20%E6%9B%B2%E7%8E%87%22%5D%0A%20%20OVER%5B%22%E5%90%8D%E4%B9%89%E7%82%B9%E8%BF%87%E6%8B%9F%E5%90%88%22%5D%20--%3E%20ROB%5B%22%E5%89%82%E9%87%8F%20%2F%20%E7%84%A6%E7%82%B9%E6%89%B0%E5%8A%A8%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20ROB%20--%3E%20F3%5B%22%E6%8B%93%E5%AE%BD%E5%9D%87%E5%80%BC%E5%B7%A5%E8%89%BA%E7%AA%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<p>这张图回答的问题是：平滑、MRC、鲁棒三项正则各自按住哪一种失败模式——对应关系错了，权重再怎么调都不对症。</p><p><span class="marginnote">「投影到 MRC」代入数字：设最小间距 20 nm、最小曲率半径 30 nm，那么优化每走一步，凡违这两条红线的像素段都会被硬性「拍」回合法值——不是扣分警告，是直接归位。也正因为是硬归位，红线定得太紧，梯度与投影就会互相拉锯，收敛明显变慢。</span></p><h3 id="鲁棒项是对随机的弱代用品" tabindex="-1">鲁棒项是对随机的弱代用品 <a class="header-anchor" href="#鲁棒项是对随机的弱代用品" aria-label="Permalink to &quot;鲁棒项是对随机的弱代用品&quot;">​</a></h3><p>扰动损失买的是均值工艺窗，不是泊松尾。缺孔仍要剂量与胶，见<a href="/litho/photon-shot-budget">光子预算</a>。把鲁棒 ILT 写成「已经解决随机」，越权。它解决的是名义点过拟合。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>伴随梯度本身是光滑的，因为成像低通。无约束时，下降方向已经倾向曲线。真正长出像素噪声的，是损失对零空间不敏感：数值误差在零空间里累积。正则给零空间一个斜率，让优化器宁愿走光滑解。MRC 投影把解再拉到可写集合；若投影与梯度冲突，表现为边角被反复拉出又拍回，收敛变慢——那是约束太紧或模型在要求不可写的对比。</p><p>模型误差会被逆放大：校准漏洞变成纹理。独立硅数据验证因此是正则的一部分，不是优化结束后的礼貌检查。</p><p><span class="marginnote">为什么独立硅数据是正则闭环的一部分：逆问题会把模型的每个漏洞放大成掩模上「看起来有道理」的奇怪纹理。用同一套模型自查，等于让学生改自己的卷子——loss 再低也不作数。必须拿没参与校准的晶圆数据回灌，才能证明正则压住的是噪声而不是信号。</span></p><p><span class="marginnote">损失下降不等于可制造。必须同时看 PV-band、MRC 违例数、掩模数据量。只报 clips 上的 EPE，等于只报未正则的训练集 loss。</span></p>',9)),(t(),E(s,null,{default:e(()=>[o(i,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22%E9%80%86%E9%97%AE%E9%A2%98%20%E9%9B%B6%E7%A9%BA%E9%97%B4%E5%A4%A7%22%5D%20--%3E%20REG%5B%22%E5%B9%B3%E6%BB%91%20%2B%20%E9%B2%81%E6%A3%92%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20REG%20--%3E%20PROJ%5B%22%E6%8A%95%E5%BD%B1%E5%88%B0%20MRC%22%5D%0A%20%20PROJ%20--%3E%20CURV%5B%22%E5%8F%AF%E5%86%99%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20INV%20--%3E%20FIT%5B%22%E8%BF%87%E6%8B%9F%E5%90%88%E7%BA%B9%E7%90%86%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>正则不增加 NA，不提高前向模型的物理正确性。它只在错误模型上也给出「看起来干净」的掩模——这时干净是假象。权重没有普适最优，随层别、写入器（VSB 对多束）和检测算法变。全芯片 ILT 的正则预算还受 GPU 日历限制：扰动点太多，班次内跑不完。热区 ILT 与全芯片 ILT 可以用不同权重，但不能用两套互相矛盾的 MRC，否则拼接处会裂开。</p><p>后课默认：ILT 的解已经是正则化之后的；下一课把投影所落的集合写成掩模厂的规则语言。</p><p>无扰动、无 MRC 的像素解可以留在实验室 clips 里当光学上限，不能当作 TAPOUT 输入。</p><p><span class="marginnote">比较 ILT 与 OPC 时写清正则项。无 MRC、无 PV 扰动的「裸逆」窗口，不能当作量产曲线掩模的收益。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>成像低通使 ILT 逆问题病态，必须正则才能落到可制造掩模。</li><li>平滑、MRC 投影、剂量/焦点鲁棒是通称的三项，缺一则过拟合或不可写。</li><li>正则不是强制曼哈顿；曲线解仍要曲率与宽度约束。</li><li>模型误差会被放大，独立硅验证属于正则闭环。</li><li>出处：逆光刻文献对病态逆问题与可制造正则的通称。</li></ul>',7))])}const C=n(A,[["render",d]]);export{u as __pageData,C as default};
